const seaFangSheet=new Image();seaFangSheet.assetSrc='assets/sea-fang-v2.png';
function beginSeaFang(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'seaOpposedTusks',bespoke:true,windup:1,origin:{x:e.x,y:e.y},angle,front:false,turned:false,rear:false};}
function seaFangContains(a,point,rear=false){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,angle=Math.atan2(dy,dx)-a.angle-(rear?Math.PI:0);angle=Math.atan2(Math.sin(angle),Math.cos(angle));return Math.hypot(dx,dy)<=180+1e-8&&Math.abs(angle)<=(rear?65:55)*Math.PI/180+1e-8;}
const seaFangAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e0')return seaFangAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='seaOpposedTusks'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=180&&clear){beginSeaFang(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,80*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,24)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.front&&e.elapsed>=1){a.front=true;e.struck=true;if(seaFangContains(a,p)&&lineClear(a.origin,p))hurt(64);playSound('impact',e.x,e.y);}if(!a.turned&&e.elapsed>=1.2){a.turned=true;a.windup=1.85;e.struck=false;}if(!dead&&!a.rear&&e.elapsed>=1.85){a.rear=true;e.struck=true;if(seaFangContains(a,p,true)&&lineClear(a.origin,p))hurt(76);playSound('impact',e.x,e.y);}if(e.elapsed>=2.85){e.attack=null;e.state='idle';e.t=2.5;}
};
const seaFangDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e0'||!seaFangSheet.complete||!seaFangSheet.naturalWidth||!seaFangSheet.naturalHeight)return seaFangDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),turn=1;if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='seaOpposedTusks'){let rear=e.elapsed>=1.2;turn=rear?-1:1;f={row:2,col:e.elapsed<.6?0:e.elapsed<1?1:e.elapsed<1.2?2:e.elapsed<1.85?1:e.elapsed<2.15?2:3};}let q=project(e.x,e.y),sw=seaFangSheet.naturalWidth/4,sh=seaFangSheet.naturalHeight/3,w=285,h=w*sh/sw,anchor=[.85,.83,.81][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale((e.facing||1)*turn,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,seaFangSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(seaFangSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const seaFangSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e0'?180:seaFangSizeBase(e);
const seaFangGroundBase=drawGroundEffects;drawGroundEffects=()=>{seaFangGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e0'):enemies)){let a=e.attack;if(e.species!=='r8e0'||e.hp<=0||a?.pattern!=='seaOpposedTusks'||!visibleAt(e.x,e.y))continue;if(e.elapsed>=2.15){groundRing(e.x,e.y,40,'#9bddcf',2);continue;}let rear=e.elapsed>=1.2,angle=a.angle+(rear?Math.PI:0),half=(rear?65:55)*Math.PI/180,fired=rear?a.rear:a.front,q=project(a.origin.x,a.origin.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=fired?'#b6e9ef66':'#6faaba22';ctx.strokeStyle=rear?'#dab484':'#9bcfd7';ctx.lineWidth=fired?3:1;ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,180,angle-half,angle+half);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}};
